import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE_W 8
#define TILE_H 8
#define CONV_K 11
#define CONV_CIN 3
#define STRIDE 4
#define PAD 2
#define OC_TILE 12
#define THREAD_TILE_W 1
#define BLOCK_DIM_X (TILE_W / THREAD_TILE_W)
#define SH_H ((TILE_H - 1) * STRIDE + CONV_K)   // 39
#define SH_W ((TILE_W - 1) * STRIDE + CONV_K)   // 39
__global__ void conv2d_forward_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C_in, int H_in, int W_in,
    int C_out, int K, int stride, int pad,
    int H_out, int W_out)
{
    // Shared memory tiles: input patch for all input channels (reused across OC_TILE output channels),
    // and weights for OC_TILE output channels of this block.
    __shared__ float sh_input[CONV_CIN][SH_H][SH_W];
    __shared__ float sh_weight[OC_TILE][CONV_CIN][CONV_K][CONV_K];
    int tx = threadIdx.x; // 0..BLOCK_DIM_X-1
    int ty = threadIdx.y; // 0..TILE_H-1
    int tid = ty * BLOCK_DIM_X + tx;
    int num_threads = BLOCK_DIM_X * TILE_H;
    int oc_groups = C_out / OC_TILE;
    int nc = blockIdx.z; // combined batch and out_channel group
    int n = nc / oc_groups;
    int oc_group = nc % oc_groups;
    int oc_base = oc_group * OC_TILE;
    // Register blocking: each thread computes THREAD_TILE_W output columns to reuse
    // weight values loaded from shared memory across multiple output pixels.
    int ow0 = blockIdx.x * TILE_W + tx * THREAD_TILE_W;
    int oh = blockIdx.y * TILE_H + ty;
    int in_h_origin = blockIdx.y * TILE_H * stride - pad;
    int in_w_origin = blockIdx.x * TILE_W * stride - pad;
    // Cooperative load of the input patch (all channels) into shared memory.
    // This tile is now reused across OC_TILE output channels, reducing redundant global loads.
    int total_input_elems = CONV_CIN * SH_H * SH_W;
    for (int idx = tid; idx < total_input_elems; idx += num_threads) {
        int ic = idx / (SH_H * SH_W);
        int rem = idx % (SH_H * SH_W);
        int sh_row = rem / SH_W;
        int sh_col = rem % SH_W;
        int gh = in_h_origin + sh_row;
        int gw = in_w_origin + sh_col;
        float val = 0.0f;
        if (n < N && gh >= 0 && gh < H_in && gw >= 0 && gw < W_in) {
            val = input[((n * C_in + ic) * H_in + gh) * W_in + gw];
        }
        sh_input[ic][sh_row][sh_col] = val;
    }
    // Cooperative load of the weights for OC_TILE output channels into shared memory
    int total_weight_elems = OC_TILE * CONV_CIN * CONV_K * CONV_K;
    for (int idx = tid; idx < total_weight_elems; idx += num_threads) {
        int oc_off = idx / (CONV_CIN * CONV_K * CONV_K);
        int rem = idx % (CONV_CIN * CONV_K * CONV_K);
        int ic = rem / (CONV_K * CONV_K);
        int rem2 = rem % (CONV_K * CONV_K);
        int kh = rem2 / CONV_K;
        int kw = rem2 % CONV_K;
        int oc = oc_base + oc_off;
        sh_weight[oc_off][ic][kh][kw] = weight[((oc * C_in + ic) * K + kh) * K + kw];
    }
    __syncthreads();
    if (oh >= H_out || n >= N) return;
    bool valid0 = (ow0 < W_out);
    if (!valid0) return;
    float sum[OC_TILE];
    #pragma unroll
    for (int t = 0; t < OC_TILE; ++t) {
        sum[t] = bias ? bias[oc_base + t] : 0.0f;
    }
    int local_h = ty * stride;
    int local_w0 = tx * THREAD_TILE_W * stride;
    #pragma unroll
    for (int ic = 0; ic < CONV_CIN; ++ic) {
        #pragma unroll
        for (int kh = 0; kh < CONV_K; ++kh) {
            #pragma unroll
            for (int kw = 0; kw < CONV_K; ++kw) {
                float in_val0 = sh_input[ic][local_h + kh][local_w0 + kw];
                #pragma unroll
                for (int t = 0; t < OC_TILE; ++t) {
                    float w = sh_weight[t][ic][kh][kw];
                    sum[t] += in_val0 * w;
                }
            }
        }
    }
    #pragma unroll
    for (int t = 0; t < OC_TILE; ++t) {
        output[((n * C_out + (oc_base + t)) * H_out + oh) * W_out + ow0] = sum[t];
    }
}
torch::Tensor conv2d_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int pad)
{
    input = input.contiguous();
    weight = weight.contiguous();
    bias = bias.contiguous();
    int N = input.size(0);
    int C_in = input.size(1);
    int H_in = input.size(2);
    int W_in = input.size(3);
    int C_out = weight.size(0);
    int K = weight.size(2);
    int H_out = (H_in + 2 * pad - K) / stride + 1;
    int W_out = (W_in + 2 * pad - K) / stride + 1;
    auto output = torch::empty({N, C_out, H_out, W_out}, input.options());
    dim3 block(BLOCK_DIM_X, TILE_H, 1);
    int oc_groups = C_out / OC_TILE;
    dim3 grid((W_out + TILE_W - 1) / TILE_W,
               (H_out + TILE_H - 1) / TILE_H,
               N * oc_groups);
    conv2d_forward_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C_in, H_in, W_in,
        C_out, K, stride, pad,
        H_out, W_out);
    return output;
}
"""
conv_header = r"""
torch::Tensor conv2d_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int pad);
"""

conv_ext = load_inline(
    name="custom_conv2d",
    cpp_sources=conv_header,
    cuda_sources=conv_source,
    functions=["conv2d_forward_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        self.out_channels = 96
        self.in_channels = 3
        self.kernel_size = 11
        self.stride = 4
        self.padding = 2

        weight = torch.empty(self.out_channels, self.in_channels, self.kernel_size, self.kernel_size)
        bias = torch.empty(self.out_channels)

        # Match nn.Conv2d default initialization
        nn.init.kaiming_uniform_(weight, a=5**0.5)
        fan_in = self.in_channels * self.kernel_size * self.kernel_size
        bound = 1 / (fan_in ** 0.5)
        nn.init.uniform_(bias, -bound, bound)

        self.weight = nn.Parameter(weight)
        self.bias = nn.Parameter(bias)

    def forward(self, x):
        x = x.cuda().contiguous()
        return conv_ext.conv2d_forward_cuda(
            x, self.weight, self.bias, self.stride, self.padding
        )


def get_inputs():
    batch_size = 256
    return [torch.rand(batch_size, 3, 224, 224)]


def get_init_inputs():
    num_classes = 1000
    return [num_classes]

